sys_script_client.script:
function onSubmit() {
    var validFrom = g_form.getValue('valid_from');
    var validTo = g_form.getValue('valid_to');
    var renewalDue = g_form.getValue('renewal_due');

    g_form.clearMessages();

    if (validFrom && validTo && validTo <= validFrom) {
        g_form.addErrorMessage('Valid To date must be greater than Valid From date.');
        g_form.showFieldMsg('valid_to', 'Valid To date must be greater than Valid From date.', 'error');
        return false;
    }

    if (renewalDue) {
        if (validFrom && renewalDue < validFrom) {
            g_form.addErrorMessage('Renewal Due date must be between Valid From and Valid To dates.');
            g_form.showFieldMsg('renewal_due', 'Renewal Due date cannot be earlier than Valid From date.', 'error');
            return false;
        }
        if (validTo && renewalDue > validTo) {
            g_form.addErrorMessage('Renewal Due date must be between Valid From and Valid To dates.');
            g_form.showFieldMsg('renewal_due', 'Renewal Due date cannot be later than Valid To date.', 'error');
            return false;
        }
    }

    return true;
}
